bound=max(D.MAX_READ*10,65536)
class Reader:
    def __init__(self,inner): self.inner=inner
    def __getattr__(self,name): return getattr(self.inner,name)
    def __enter__(self): self.inner.__enter__();return self
    def __exit__(self,*args): return self.inner.__exit__(*args)
    def read(self,size=-1):
        assert 0<=size<=bound, 'unbounded allocation'
        return self.inner.read(size)
    def readinto(self,buffer):
        assert len(buffer)<=bound, 'unbounded allocation'
        return self.inner.readinto(buffer)
    def readall(self): raise AssertionError('unbounded allocation')
